  const said = (c) => (c.html || '').match(/data-said="([^"]*)"/);
  cards.forEach((c, i) => {
    if (c.kind !== 'bet' && c.kind !== 'wager') return;
    const next = cards[i + 1];
    if (!next) return fail.push(`${name}: ${c.id} is the last card, never answered`);
    const answered = (next.kind === 'reveal' && next.id === c.id)
      || (said(next) && said(next)[1].split(',').indexOf(c.id) !== -1);
    if (!answered) fail.push(`${name}: ${c.id} is followed by ${next.kind}`
      + (said(next) ? ' [said=' + said(next)[1] + ']' : '') + ', which does not answer it');
  });
  // An answer the reader has to wait for is one a fast clicker never sees.
  cards.forEach((c) => {
    if (said(c) && /pc-late/.test(c.html)) fail.push(`${name}: ${c.kind} answer is on the late fade`);
  });
  // The deck must not give a wager away before asking it.
  const kinds = cards.map((c) => c.kind);
  const beats = cards.filter((c) => c.kind === 'beat').map((c) => c.beat);
  if (kinds.includes('wager') && beats.includes('convergence'))
